function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function luckyDraw(names, opts){
  opts=opts||{}; var seed=opts.seed!=null?opts.seed:1; var r=rngFactory(seed);
  var list=(typeof names==='string' ? names.split(/[\n,，;；]+/) : (names||[]))
    .map(function(s){ return String(s).trim(); }).filter(Boolean);
  var n=opts.pick!=null?opts.pick:1;
  if(n<1) n=1;
  if(n>list.length) n=list.length;
  var arr=list.slice(); var picked=[];
  for(var i=0;i<n;i++){
    if(!arr.length) break;
    var idx=Math.floor(r()*arr.length);
    picked.push(arr[idx]);
    arr.splice(idx,1);
  }
  return {ok:true, winners:picked, drawn:picked.length, remaining:arr};
}

var EXPORTS={luckyDraw:luckyDraw};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LuckyDrawForgePure = EXPORTS; }
